            aWandererI = aWandererI ^ ((RotL64(aScatter, 19U) + aOrbiterE) + RotL64(aOrbiterA, 3U));
            aWandererF = aWandererF + ((RotL64(aIngress, 36U) + aOrbiterH) + RotL64(aOrbiterA, 23U));
            aWandererE = aWandererE ^ (((RotL64(aScatter, 3U) + RotL64(aOrbiterK, 29U)) + aOrbiterG) + aPhaseCWandererUpdateSaltE[((aIndex + 5U)) & S_SALT1]);
