            aOrbiterK = ((aWandererA + RotL64(aScatter, 23U)) + RotL64(aCarry, 23U)) + 0xB0ECF77AE6B6B797ULL;
            aOrbiterG = ((aWandererH + RotL64(aCross, 37U)) + 0xDA564CDC971B9387ULL) + aPhaseBOrbiterAssignSaltD[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterD = (aWandererJ + RotL64(aScatter, 5U)) + 0xD1324DB108F5B906ULL;
            aOrbiterH = (aWandererK + RotL64(aPrevious, 43U)) + 0x63CE8E8EDD86659FULL;
            //
            aOrbiterB = (aOrbiterB + aOrbiterF) + 0xB07E1FCD8465B0E4ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterB) ^ 0x5452AAD3E54CF46CULL;
            aOrbiterI = RotL64((aOrbiterI * 0xC2C13B76FD0E04E1ULL), 51U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterG) + 0x86D0BCAE593A785EULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterK) ^ 0x5548F4F3D7E769C7ULL) ^ aPhaseBOrbiterUpdateSaltE[((aIndex + 5U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x84965BA819FB1387ULL), 57U);
