            //
            aOrbiterF = ((aOrbiterF + aOrbiterD) + 0x8207A7C49A271DE6ULL) + aPhaseBOrbiterUpdateSaltB[((aIndex + 25U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterF) ^ 0x28CFC4D78F2D6A92ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x2E3EE0C873122E7DULL), 5U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterB) + 0x605C2F419B6F02ECULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterG) ^ 0x2DA33734ED503E46ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xE2210383D0DC0E6BULL), 23U);
