            aCross = (RotL64(aIceLaneA[((S_BLOCK1 - aIndex + 22182U)) & S_BLOCK1], 58U) ^ RotL64(aHeartLaneB[((S_BLOCK1 - aIndex + 18250U)) & S_BLOCK1], 37U));
