            //
            aOrbiterK = (((aWandererH + RotL64(aPrevious, 29U)) + RotL64(aCarry, 13U)) + 0x134F03916720D85EULL) + aPhaseCOrbiterAssignSaltE[((aIndex + 4U)) & S_SALT1];
            aOrbiterJ = (aWandererI + RotL64(aIngress, 21U)) + 0x1F50F30489A890E9ULL;
            aOrbiterD = ((aWandererJ + RotL64(aCross, 47U)) + RotL64(aCarry, 39U)) + 0x4374327E054404BDULL;
            aOrbiterC = (aWandererG + RotL64(aScatter, 13U)) + 0xFA9EFBDDFB7F2CA2ULL;
            aOrbiterI = (aWandererD + RotL64(aIngress, 37U)) + 0x3E0EE542455A1973ULL;
            aOrbiterG = (((aWandererE + RotL64(aScatter, 3U)) + RotL64(aCarry, 27U)) + 0x202F53BDCA1C9088ULL) + aPhaseCOrbiterAssignSaltA[((aIndex + 29U)) & S_SALT1];
            aOrbiterE = (aWandererA + RotL64(aCross, 56U)) + 0x6A8A3AB0A03A2478ULL;
            //
            aOrbiterK = (aOrbiterK + aOrbiterJ) + 0x157572846A5A9809ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterK) ^ 0x5532575506B8E5F5ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xDBEF773BF58A136DULL), 29U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterC) + 0x54B258EF6267847CULL) + aPhaseCOrbiterUpdateSaltE[((aIndex + 17U)) & S_SALT1];
