            aOrbiterJ = RotL64((aOrbiterJ * 0xDD348DC8C094561FULL), 5U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterD) + 0x2DB76147D79C4A97ULL) + aPhaseCOrbiterUpdateSaltD[((aIndex + 15U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterJ) ^ 0xA3CE7889C7B063A3ULL;
