            //
            aOrbiterC = (aOrbiterC + aOrbiterI) + 0xBDCC5684B417CFC1ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterC) ^ 0x70D0B8D520EE695EULL) ^ aPhaseCOrbiterUpdateSaltB[(((31U - aIndex) + 20U)) & S_SALT1];
