            //
            aOrbiterI = ((aOrbiterI + aOrbiterE) + 0xAA439A272950EEB9ULL) + aPhaseCOrbiterUpdateSaltF[((aIndex + 25U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterI) ^ 0x70678885C52AC071ULL;
