            aOrbiterI = (aWandererA + RotL64(aCross, 43U)) + 0x35E34D6329B8C2E9ULL;
            aOrbiterA = ((aWandererD + RotL64(aIngress, 51U)) + 0xC9281176D2BB9787ULL) + aPhaseDOrbiterAssignSaltF[((aIndex + 25U)) & S_SALT1];
            aOrbiterK = (aWandererK + RotL64(aPrevious, 5U)) + 0x24A7F1216532B01EULL;
