            aOrbiterK = ((aOrbiterK + aOrbiterF) + 0xA3A028B37D115ED3ULL) + aPhaseDOrbiterUpdateSaltA[((aIndex + 21U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterK) ^ 0xBB31910C172266EEULL;
